import {STATUSES,count,available,watch,undo,minutes,validateBackup,episodeWatched,nextEpisode} from './model.js?v=4';
import {GENRES,filterTitles,matchesFilters,animeSearchUrl,} from './catalog-tools.js?v=4';
import {beginWatching,completeWatching,syncWatchSession} from './watch-session.js?v=4';
import {providerFrameUrl,withEpisode,kinopoiskId,episodeCoordinates} from './embedded-player.js?v=4';

const icons={moon:'<path d="M20.7 13A9 9 0 0 1 11 3.3 9 9 0 1 0 20.7 13Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',list:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 8 1 1 2-2m2 1h3M8 14h2m3 0h3m-8 3h8"/>',history:'<path d="M3 11a9 9 0 1 1 2.6 7M3 4v7h7m2-4v5l3 2"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',play:'<path d="m9 5 11 7-11 7Z"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-10 4h2"/>',plus:'<path d="M12 5v14M5 12h14"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',cloud:'<path d="M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11 1 4.5 4.5 0 0 1 0 9M9 15l3 3 3-3m-3 3v-7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4m-4 8h4M17 8h4m-4 8h4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.film}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=url=>{try{const u=new URL(url,location.href);return ['http:','https:'].includes(u.protocol)?esc(u.href):'';}catch{return '';}};
const $=s=>document.querySelector(s);
const KEY='yoru-library-v1';
let catalog=[],state,view='dashboard',filter='all',kind='all',sort='recent',query='',searchResults=[],searchBusy=false,searchNotice='',searchToken=0,menuOpen=false;
let persistenceBroken=false;
let searchFilters={genres:[],minScore:0,maxScore:10,order:'relevance'},hasSearched=false,searchPageNumber=1,searchHasMore=false,genresOpen=false,lastCompleteAt=0,searchDraft='';
const getTitle=id=>catalog.find(t=>t.id===id);
const watched=id=>count(state,id);
const fmtTime=n=>`${Math.floor(n/60)} ч${n%60?' '+Math.round(n%60)+' мин':''}`;
const num=n=>new Intl.NumberFormat('ru-RU').format(n);
const dayKey=at=>new Date(at).toLocaleDateString('sv-SE');
const today=()=>dayKey(Date.now());
function save(){try{localStorage.setItem(KEY,JSON.stringify({state,catalog}));}catch{persistenceBroken=true;toast('Не удалось сохранить данные. Экспортируйте резервную копию в профиле.');}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function emptyState(){return {name:'Зритель',demo:false,entries:{},events:[],createdAt:new Date().toISOString()};}
function entries(status){return Object.entries(state.entries).filter(([id,e])=>getTitle(id)&&(!status||e.status===status));}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action||`<span class="date">${icon('calendar')}${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span>`}</div>`;}
function navItem(route,label,i){return `<a class="nav-item ${view===route?'active':''}" href="#/${route}" ${view===route?'aria-current="page"':''}>${icon(i)}${label}${route==='library'?`<span class="nav-number">${entries().length}</span>`:''}</a>`;}
function render(){
 const searchFocused=document.activeElement?.id==='search-input';
 const selection=searchFocused?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;
 const route=location.hash.slice(2).split('/');view=route[0]||'dashboard';if(!['dashboard','library','history','stats','search','title','watch'].includes(view))view='dashboard';
 if(view==='watch'){view='title';history.replaceState(null,'','#/title/'+route[1]);}
 if(view==='title'&&getTitle(route[1])&&$('#inline-iframe')&&$('#inline-player')?.dataset.id===route[1]&&playerState(getTitle(route[1])).status==='ready'){refreshInlinePlayer(getTitle(route[1]));return;}
 if(view==='library')filter=Object.hasOwn(STATUSES,route[1])?route[1]:'all';
 const labels={dashboard:'Обзор',library:'Мой список',history:'История просмотров',stats:'Статистика',search:'Поиск',title:'Тайтл',watch:'Просмотр'};
 document.title=`${['title','watch'].includes(view)?getTitle(route[1])?.title||'Тайтл':labels[view]} — Yoru`;
 $('#app').innerHTML=`<div class="shell"><div class="mobile-shade ${menuOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}"><a class="logo" href="#/dashboard">${icon('moon')}yoru<small>夜</small></a><div class="brand-note">Твоя история в эпизодах</div><p class="nav-label">ЛИЧНОЕ ПРОСТРАНСТВО</p><nav aria-label="Главная навигация">${navItem('dashboard','Обзор','grid')}${navItem('library','Мой список','list')}${navItem('history','История','history')}${navItem('stats','Статистика','chart')}${navItem('search','Найти тайтл','search')}</nav><div class="divider"></div><p class="nav-label">МОЯ КОЛЛЕКЦИЯ</p>${Object.entries(STATUSES).map(([s,label])=>`<a class="status-link" href="#/library/${s}"><i class="dot ${s}"></i>${label}<span>${entries(s).length}</span></a>`).join('')}<div class="sidebar-bottom"><span class="storage-note">${icon('cloud')}${persistenceBroken?'Не удалось сохранить':'Хранится в этом браузере'}</span><button class="profile-btn" data-action="profile"><span class="avatar">${esc(state.name[0]?.toUpperCase()||'Я')}</span><span><strong>${esc(state.name)}</strong><small>${state.demo?'Демо-профиль':'Личное пространство'}</small></span>${icon('settings')}</button></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb">Моё пространство ${icon('chevron')}<span>${labels[view]}</span></div><div class="top-tools"><form class="searchbox" id="global-search">${icon('search')}<input aria-label="Поиск аниме и сериалов" name="q" placeholder="Найти аниме или сериал…" autocomplete="off"><span class="key">Ctrl K</span></form><button class="avatar top-avatar" data-action="profile" aria-label="Настройки профиля">${esc(state.name[0]?.toUpperCase()||'Я')}</button></div></header><main class="content" id="main">${state.demo?`<div class="demo-banner"><span>Вы в демо-профиле. Попробуйте отметить серию — всё уже работает.</span><button data-action="start">Создать свой список ${icon('arrow')}</button></div>`:''}${view==='dashboard'?dashboard():view==='library'?library():view==='history'?history():view==='stats'?stats():view==='search'?searchPage():view==='watch'?watchPage(route[1]):detail(route[1])}<footer class="footer"><span>yoru · Каждая история остаётся с тобой.</span><span>Каталоги: <a href="https://shikimori.io" target="_blank" rel="noreferrer">Shikimori</a> · <a href="https://www.tvmaze.com" target="_blank" rel="noreferrer">TVmaze</a> <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA</a></span></footer></main>${watchDock()}</div></div>`;
 if(view==='search'){$('#search-input').value=searchDraft;if(searchFocused){$('#search-input').focus();$('#search-input').setSelectionRange(...selection);}}
 if(view==='title'){const t=getTitle(route[1]);if(t?.needsDetails)loadDetails(t);if(t)mountInlinePlayer(t);}
}
function statsCards(){const m=minutes(state),week=Date.now()-7*864e5;return `<div class="stats">${[
 ['clock','Время за просмотром',`${Math.floor(m/60)} <small>ч</small> ${Math.round(m%60)} <small>мин</small>`,`<span class="green">${fmtTime(state.events.filter(e=>Date.parse(e.at)>week).reduce((s,e)=>s+e.minutes,0))}</span> за последние 7 дней`],
 ['play','Просмотрено эпизодов',num(state.events.length),'Одна серия — ещё одна история'],
 ['check','Завершено тайтлов',num(entries('completed').length),'Истории, которые остались с вами'],
 ['list','В вашей коллекции',num(entries().length),`${entries('watching').length} смотрю · ${entries('planned').length} в планах`]
 ].map(([i,l,v,c])=>`<div class="stat"><div class="stat-top">${l}${icon(i)}</div><div class="stat-value">${v}</div><div class="stat-caption">${c}</div></div>`).join('')}</div>`;}
function continueCard(t){const n=watched(t.id),total=t.total||available(t),limit=available(t);return `<article class="continue-card"><a class="card-visual" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="${esc(t.title)}" loading="lazy"><span class="kind-tag">${t.kind==='anime'?'АНИМЕ':'СЕРИАЛ'} · ${t.year||'—'}</span></a><div class="card-body"><a class="title-link" href="#/title/${esc(t.id)}" title="${esc(t.title)}">${esc(t.title)}</a><div class="subtitle">${esc(t.original)}</div><div class="progress-label"><span>Эпизод ${n} <span>/ ${total||'?'}</span></span><b>${total?Math.round(n/total*100)+'%':'В процессе'}</b></div><div class="progress-track"><span style="width:${total?Math.min(n/total*100,100):0}%"></span></div><div class="card-bottom"><a class="watch-quick" href="#/title/${esc(t.id)}">${limit!==null&&n>=limit?'Все серии отмечены':`Смотреть · эп. ${state.activeWatch?.titleId===t.id?state.activeWatch.episode:nextEpisode(state,t.id)}`}</a><button class="add-episode" data-action="watch" data-id="${esc(t.id)}" ${limit!==null&&n>=limit?'disabled':''} aria-label="Отметить следующую серию: ${esc(t.title)}">+1 серия</button></div></div></article>`;}
function posterCard(t,progress=false){return `<article class="poster-card"><a class="poster" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="Постер: ${esc(t.title)}" loading="lazy">${t.score?`<span class="score">${icon('star')}${Number(t.score).toFixed(1)}</span>`:''}</a><a class="title-link" href="#/title/${esc(t.id)}" title="${esc(t.title)}">${esc(t.title)}</a><div class="poster-meta">${progress?`<i class="dot ${state.entries[t.id].status}"></i>${esc(STATUSES[state.entries[t.id].status])}`:`${t.year||'—'}<i></i>${t.kind==='anime'?'Аниме':'Сериал'}`}</div>${progress?`<div class="progress-label"><span>${watched(t.id)} / ${t.total||available(t)||'?'} эп.</span><span>${fmtTime(state.events.filter(e=>e.titleId===t.id).reduce((s,e)=>s+e.minutes,0))}</span></div><div class="progress-track"><span style="width:${Math.min(100,watched(t.id)/(t.total||available(t)||Infinity)*100)}%"></span></div>`:''}</article>`;}
function section(title,i,content,href,label='Все тайтлы'){return `<div class="section-head"><div class="section-title">${icon(i)}<h2>${title}</h2></div><a class="text-link" href="${href}">${label}${icon('arrow')}</a></div>${content}`;}
function empty(title,text,link='#/search',label='Найти тайтл'){return `<div class="empty">${icon('moon')}<h3>${title}</h3><p>${text}</p><a class="btn" href="${link}">${icon('search')}${label}</a></div>`;}
function dashboard(){const watching=entries('watching').sort((a,b)=>b[1].updatedAt-a[1].updatedAt).slice(0,4).map(([id])=>getTitle(id));const picks=catalog.filter(t=>!state.entries[t.id]||['planned','paused'].includes(state.entries[t.id].status)).slice(0,6);return `${heading(`Хорошего просмотра, ${esc(state.name)} <span style="color:#b6a0ff">✦</span>`,'Все ваши миры. В одном месте.')}<section class="hero"><div class="hero-art" aria-hidden="true"></div><div class="hero-text"><span class="eyebrow">ВАШ ЛИЧНЫЙ WATCHLIST</span><h2>Ещё одна серия —<br>ещё одна история.</h2><p>Сохраняйте то, что любите.<br>А мы поможем не потерять ни одного эпизода.</p><a class="btn" href="#/search">${icon('plus')}Найти новую историю</a></div></section>${statsCards()}${section('Продолжить просмотр','play',watching.length?`<div class="continue-grid">${watching.map(continueCard).join('')}</div>`:empty('Здесь начнётся ваша история','Найдите аниме или сериал, выберите «Смотрю» и отмечайте просмотренные серии.'),'#/library/watching','Мой список')}${section('Следующая история','spark',`<div class="discovery">${picks.map(t=>posterCard(t)).join('')}</div>`,'#/search','Открыть каталог')}`;}
function library(){let list=entries(filter==='all'?null:filter).map(([id])=>getTitle(id)).filter(t=>kind==='all'||t.kind===kind);list.sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'ru'):sort==='progress'?watched(b.id)-watched(a.id):state.entries[b.id].updatedAt-state.entries[a.id].updatedAt);return `${heading('Мой список','Большие миры и маленькие планы.',`<a class="btn" href="#/search">${icon('plus')}Добавить тайтл</a>`)}<div class="tabs" role="tablist" aria-label="Статус просмотра">${[['all','Все'],...Object.entries(STATUSES)].map(([s,label])=>`<button role="tab" aria-selected="${filter===s}" class="tab ${filter===s?'active':''}" data-action="filter" data-value="${s}">${label}<span>${s==='all'?entries().length:entries(s).length}</span></button>`).join('')}</div><div class="toolbar">${kindFilters()}<select class="select" id="sort-select" aria-label="Сортировка">${[['recent','Недавно добавленные'],['name','По названию'],['progress','По прогрессу']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div>${list.length?`<div class="library-grid">${list.map(t=>posterCard(t,true)).join('')}</div>`:empty('Пока ни одного тайтла','В этом списке ещё нет историй. Самое время найти что-нибудь интересное.')}`;}
function kindFilters(){return `<div class="segmented" aria-label="Тип тайтла">${[['all','Все'],['anime','Аниме'],['tv','Сериалы']].map(([v,l])=>`<button class="segment ${kind===v?'active':''}" data-action="kind" data-value="${v}" aria-pressed="${kind===v}">${l}</button>`).join('')}</div>`;}
function history(){const events=[...state.events].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));const groups=Map.groupBy?Map.groupBy(events,e=>dayKey(e.at)):events.reduce((map,e)=>{const d=dayKey(e.at);map.set(d,[...(map.get(d)||[]),e]);return map;},new Map());return `${heading('История просмотров','Моменты, из которых складываются ваши истории.')}<div class="toolbar"><span class="filter-label">${num(events.length)} эпизодов · ${fmtTime(minutes(state))}</span><button class="btn ghost" data-action="export">${icon('download')}Экспорт данных</button></div>${events.length?[...groups].map(([day,es])=>`<section class="history-group"><h2 class="history-date">${day===today()?'Сегодня':new Date(day+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}<span style="float:right">${fmtTime(es.reduce((n,e)=>n+e.minutes,0))}</span></h2>${es.map(e=>{const t=getTitle(e.titleId);return `<a class="history-row" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="" loading="lazy"><div class="info"><strong>${esc(t.title)}</strong><small>Эпизод ${e.episode}${t.episodeData?.[e.episode-1]?.label?' · '+esc(t.episodeData[e.episode-1].label):''}</small></div><time>${new Date(e.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time><span class="history-min">+ ${e.minutes} мин</span>${icon('check')}</a>`;}).join('')}</section>`).join(''):empty('Всё только начинается','Отметьте первую просмотренную серию. Здесь появятся дата, эпизод и время просмотра.')}`;}
function stats(){const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);return {key:dayKey(date),label:date.toLocaleDateString('ru-RU',{weekday:'short'}),minutes:state.events.filter(e=>dayKey(e.at)===dayKey(date)).reduce((s,e)=>s+e.minutes,0)};});const max=Math.max(...days.map(d=>d.minutes),60);return `${heading('Ваша статистика','Время, проведённое в любимых мирах.')}${statsCards()}<section class="chart-box"><div class="section-head"><h2>Последние 7 дней</h2><span class="filter-label">Минуты просмотра</span></div><div class="chart" role="img" aria-label="Время просмотра за неделю: ${days.map(d=>d.label+' '+d.minutes+' минут').join(', ')}">${days.map(d=>`<div class="chart-col"><small>${d.minutes||'—'}</small><div class="chart-bar" style="height:${d.minutes/max*85}%"></div><span>${d.label}</span></div>`).join('')}</div></section><div class="type-stats">${[['anime','Аниме','spark'],['tv','Сериалы','film']].map(([k,l,i])=>{const ev=state.events.filter(e=>getTitle(e.titleId)?.kind===k);return `<div class="type-stat"><span class="section-title">${icon(i)}${l}</span><strong>${fmtTime(ev.reduce((s,e)=>s+e.minutes,0))}</strong><p>${ev.length} эпизодов · ${entries().filter(([id])=>getTitle(id).kind===k).length} тайтлов в коллекции</p></div>`;}).join('')}</div>`;}
function localSearch(q){const norm=s=>s.toLocaleLowerCase('ru').replace(/ё/g,'е');return catalog.filter(t=>[t.title,t.original,...(t.aliases||[])].filter(Boolean).some(s=>norm(s).includes(norm(q))));}
function filterPanel(){
 const selected=searchFilters.genres;
 return `<section class="filters-panel" aria-label="Фильтры поиска"><div class="filter-top">${kindFilters()}<button class="text-link" data-action="reset-search">Сбросить фильтры</button></div><div class="filter-fields"><details class="genre-filter" ${genresOpen?'open':''}><summary>Жанры <span>${selected.length?selected.length:'Все'}</span></summary><div class="genre-options"><p>Совпадают все выбранные жанры</p>${GENRES.map(g=>`<label><input type="checkbox" data-genre="${g.id}" ${selected.includes(g.id)?'checked':''}>${g.label}</label>`).join('')}</div></details><label class="filter-field">Оценка от<select id="score-min" class="select">${Array.from({length:11},(_,i)=>`<option value="${i}" ${searchFilters.minScore===i?'selected':''}>${i===0?'Любая':i+' / 10'}</option>`).join('')}</select></label><label class="filter-field">Оценка до<select id="score-max" class="select">${Array.from({length:11},(_,i)=>`<option value="${i}" ${searchFilters.maxScore===i?'selected':''}>${i} / 10</option>`).join('')}</select></label><label class="filter-field">Сортировка<select id="search-order" class="select">${[['relevance','По соответствию'],['score-desc','Сначала высокий рейтинг'],['score-asc','Сначала низкий рейтинг'],['year','Сначала новые'],['title','По названию']].map(([v,l])=>`<option value="${v}" ${searchFilters.order===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${selected.length?`<div class="selected-genres">${selected.map(id=>`<button data-action="remove-genre" data-value="${id}">${esc(GENRES.find(g=>g.id===id)?.label)} ${icon('close')}</button>`).join('')}</div>`:''}</section>`;
}
function searchPage(){
 const list=filterTitles(hasSearched?searchResults:catalog,{...searchFilters,kind});
 return `${heading('Найти свою историю','Выберите жанры, оценку и мир по настроению.')}<form class="search-large" id="catalog-search">${icon('search')}<input id="search-input" name="q" aria-label="Название тайтла" placeholder="Название аниме или сериала…" autocomplete="off"><button class="btn" type="submit">Найти ${icon('arrow')}</button></form>${filterPanel()}<div class="search-summary"><p class="search-note">${searchBusy?'<span class="loading">Ищем в каталогах…</span>':query?`По запросу «${esc(query)}» · найдено ${list.length}`:`Найдено тайтлов: ${list.length}`}${searchNotice?`<br>${esc(searchNotice)}`:''}</p><button class="text-link" data-action="manual">${icon('plus')}Добавить вручную</button></div>${list.length?`<div class="library-grid">${list.map(t=>posterCard(t)).join('')}</div>`:searchBusy?'<div class="empty"><div class="loading">Ищем вашу следующую историю…</div></div>':empty('По этим фильтрам ничего не нашлось','Попробуйте расширить диапазон оценок, убрать один из жанров или изменить название.','#/search','Изменить поиск')}${searchHasMore?`<div class="load-more"><button class="btn secondary" data-action="search-more" ${searchBusy?'disabled':''}>${searchBusy?'Загрузка…':'Загрузить ещё'}</button></div>`:''}`;
}
function legacyDetail(id){const t=getTitle(id);if(!t)return empty('Тайтл не найден','Вернитесь к поиску и выберите нужный результат.');const n=watched(id),released=available(t),status=state.entries[id]?.status,limit=released;return `<a href="#/library" class="detail-back">${icon('back')}К моему списку</a><section class="detail-hero"><div class="detail-poster"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt="${esc(t.title)}"></div><div class="detail-main"><div class="detail-title"><span class="eyebrow">${t.kind==='anime'?'АНИМЕ':'СЕРИАЛ'} · ${t.year||'—'}${t.score?' · ★ '+t.score:''}</span><h1>${esc(t.title)}</h1><div class="detail-original">${esc(t.original)}</div><div class="tags">${(t.genres||[]).slice(0,4).map(g=>`<span class="tag">${esc(genreRu[g]||g)}</span>`).join('')}<span class="tag">${t.airing?'Продолжается':'Завершён'}</span></div></div><div class="detail-info"><div><span>Вышло эпизодов</span><b>${t.needsDetails?'Загрузка…':released===null?'Нет данных':released}</b></div><div><span>Всего эпизодов</span><b>${t.total||'Не объявлено'}</b></div><div><span>Один эпизод</span><b>${t.duration?t.duration+' мин':'Не указано'}</b></div></div><p class="synopsis">${esc(ruDescriptions[t.id]||t.description||'У этой истории пока нет описания. Добавьте её в список и начните просмотр.')}</p><div class="detail-actions"><button class="btn" data-action="start-player" data-id="${esc(id)}">${icon('play')}Смотреть онлайн</button><select class="select" id="title-status" data-id="${esc(id)}" aria-label="Статус просмотра"><option value="" ${!status?'selected':''}>Добавить в список…</option>${Object.entries(STATUSES).map(([s,l])=>`<option value="${s}" ${status===s?'selected':''}>${l}</option>`).join('')}</select>${t.apiId?`<button class="btn ghost" data-action="refresh" data-id="${esc(id)}">Обновить данные</button>`:`<button class="btn ghost" data-action="edit-manual" data-id="${esc(id)}">Редактировать</button>`}${!t.duration?`<button class="btn secondary" data-action="duration" data-id="${esc(id)}">Указать длительность</button>`:''}</div>${t.source?`<a class="source-link" href="${safeUrl(t.source)}" target="_blank" rel="noreferrer">Информация: ${t.kind==='anime'?'Shikimori':'TVmaze'} ↗</a>`:''}</div></section><section class="tracking-panel"><div class="tracking-top"><div><h2>Ваш прогресс</h2><p>${status?STATUSES[status]:'Добавьте тайтл или отметьте первую серию'}</p></div><div class="tracking-count">${n} <small>/ ${t.total||released||'?'} эп.</small></div></div><div class="progress-track"><span style="width:${Math.min(n/(t.total||released||Infinity)*100,100)}%"></span></div><div class="tracking-controls"><button class="btn" data-action="watch" data-id="${esc(id)}" ${t.needsDetails||(limit!==null&&n>=limit)||!t.duration?'disabled':''}>${icon('plus')}${limit!==null&&n>=limit?'Все вышедшие серии отмечены':'Посмотрел серию '+(n+1)}${t.duration&&!(limit!==null&&n>=limit)?' · '+(t.episodeData?.[n]?.duration||t.duration)+' мин':''}</button><button class="btn ghost" data-action="undo" data-id="${esc(id)}" ${!n?'disabled':''}>${icon('back')}Отменить последнюю</button></div><div class="tracking-note">${fmtTime(state.events.filter(e=>e.titleId===id).reduce((s,e)=>s+e.minutes,0))} за просмотром этого тайтла. Каждая отметка добавляет эпизод и его длительность в историю.${released===null?' Число вышедших серий неизвестно: прогресс отмечается вручную.':''}${t.detailError?' Не удалось обновить сведения об эпизодах. Попробуйте открыть карточку позже.':''}</div>${(t.total||released||n)?`<div class="episode-grid" aria-label="Просмотренные эпизоды">${Array.from({length:Math.min(t.total||released||n+1,120)},(_,i)=>`<button class="ep ${i<n?'seen':i===n?'next':''}" ${i===n&&!t.needsDetails&&(limit===null||i<limit)?`data-action="watch" data-id="${esc(id)}" aria-label="Отметить эпизод ${i+1}"`:'disabled'} title="Эпизод ${i+1}${i<n?' просмотрен':''}">${i<n?'✓':i+1}</button>`).join('')}</div>`:''}</section>`;}
const genreRu={Action:'Экшен',Adventure:'Приключения',Drama:'Драма',Fantasy:'Фэнтези',Comedy:'Комедия',Mystery:'Мистика',Thriller:'Триллер',Romance:'Романтика',Supernatural:'Сверхъестественное',Horror:'Ужасы',Suspense:'Саспенс','Sci-Fi':'Фантастика',ScienceFiction:'Фантастика','Science-Fiction':'Фантастика'};
const ruDescriptions={'anime-52991':'После победы над королём демонов эльфийская волшебница Фрирен отправляется в новое путешествие. Спустя десятилетия она начинает понимать, что значили для неё люди, с которыми она когда-то спасла мир. Тихая история о времени, памяти и умении быть рядом.','anime-44511':'Дэндзи мечтает о простой жизни: еде, крыше над головой и ком-то рядом. Но договор с демоном-бензопилой меняет всё — теперь он охотник на демонов в мире, где любая мечта имеет свою цену.','anime-40748':'Обычный школьник Юдзи Итадори оказывается в мире проклятий и магов. Вместе с новыми друзьями он учится управлять силой, которая одновременно даёт шанс спасти других и угрожает ему самому.','anime-16498':'За огромными стенами человечество скрывается от титанов. Когда привычный мир рушится, Эрен и его друзья вступают в борьбу за свободу — и постепенно узнают, насколько велика цена правды.','tv-44933':'Сотрудники корпорации Lumon добровольно проходят процедуру, разделяющую воспоминания о работе и личной жизни. Но идеальный баланс начинает трещать по швам, когда одна из личностей решает узнать, что находится по другую сторону лифта.'};
async function fetchJson(url){const response=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Каталог временно недоступен');return response.json();}
function animeFrom(a){return {id:'anime-'+a.id,apiId:a.id,provider:'shikimori',kind:'anime',title:a.russian||a.name,original:(a.english||[]).find(Boolean)||a.name,aliases:[a.name,...(a.english||[]),...(a.synonyms||[])].filter(Boolean),poster:a.image?.original?'https://shikimori.io'+a.image.original:null,total:a.episodes||null,released:a.status==='released'?a.episodes||null:a.episodes_aired??null,duration:a.duration||null,year:a.aired_on?.slice(0,4),score:Number(a.score)||null,genres:(a.genres||[]).map(g=>g.russian||g.name),description:(a.description||'').replace(/\[\/?[^\]]+\]/g,''),airing:a.status!=='released',source:'https://shikimori.io'+a.url,needsDetails:!a.duration};}
function tvFrom(a){return {id:'tv-'+a.id,apiId:a.id,kind:'tv',imdbId:a.externals?.imdb,officialSite:a.officialSite,streamingName:a.webChannel?.name||a.network?.name,title:a.name,original:a.name,aliases:[],poster:a.image?.original||a.image?.medium,total:null,released:null,duration:a.averageRuntime||a.runtime||null,year:a.premiered?.slice(0,4),score:a.rating?.average,genres:a.genres||[],description:(a.summary||'').replace(/<[^>]+>/g,''),airing:a.status!=='Ended',source:a.url,needsDetails:true};}
function mergeFoundTitle(t){
 const existing=getTitle(t.id);
 if(!existing){catalog.push(t);return t;}
 if(!existing.genres?.length){existing.genreHints=[...new Set([...(existing.genreHints||[]),...(t.genreHints||[])])];if(t.genres?.length)existing.genres=t.genres;}
 if(t.imdbId)existing.imdbId=t.imdbId;
 return existing;
}
async function search(q,{append=false}={}){
 query=q.trim();searchDraft=q;hasSearched=true;const token=++searchToken;
 const page=append?searchPageNumber+1:1,filters={...searchFilters,genres:[...searchFilters.genres],kind};
 if(!append)searchResults=localSearch(query);searchBusy=true;searchNotice='';render();
 const alias=searchResults.find(t=>t.title.toLowerCase()===query.toLowerCase())?.original;
 const jobs=[];const animeUrl=animeSearchUrl(query,filters,page);
 if(kind!=='tv'&&animeUrl)jobs.push(['anime',animeUrl]);
 if(kind!=='anime'&&(!append||!query))jobs.push(['tv',query?`https://api.tvmaze.com/search/shows?q=${encodeURIComponent(alias||query)}`:`https://api.tvmaze.com/shows?page=${page-1}`]);
 const results=await Promise.allSettled(jobs.map(async([provider,url])=>{
  const data=await fetchJson(url);
  const raw=provider==='anime'?data.map(a=>({...animeFrom(a),genreHints:[...filters.genres]})):(query?data.map(x=>x.show):data).map(tvFrom);
  return {provider,more:provider==='anime'?raw.length===24:!query&&raw.length>0,titles:raw.filter(t=>matchesFilters(t,filters))};
 }));
 if(token!==searchToken)return;
 const found=new Map(searchResults.map(t=>[t.id,t]));let failures=0;searchHasMore=false;
 for(const result of results){if(result.status==='rejected'){failures++;continue;}searchHasMore ||= result.value.more;for(const t of result.value.titles){const merged=mergeFoundTitle(t);found.set(merged.id,merged);}}
 searchResults=[...found.values()];searchPageNumber=page;searchBusy=false;
 searchNotice=failures?'Часть каталогов временно недоступна. Показаны доступные результаты.':!query&&kind!=='anime'?'Для поиска сериалов во всём каталоге укажите название. «Загрузить ещё» расширяет текущую подборку.':'Оценки каталогов по шкале от 0 до 10. Тайтлы без оценки не попадают в заданный диапазон.';
 save();if(view==='search')render();
}
const loadingDetails=new Set();async function loadDetails(t){if(loadingDetails.has(t.id))return;loadingDetails.add(t.id);try{if(t.kind==='tv'){const eps=await fetchJson(`https://api.tvmaze.com/shows/${t.apiId}/episodes`);t.episodeData=eps.map(e=>({duration:e.runtime||t.duration||null,airdate:e.airstamp,label:`S${String(e.season).padStart(2,'0')}E${String(e.number||0).padStart(2,'0')}`}));t.released=available(t);t.total=t.airing?null:eps.length;}else{const a=await fetchJson(`https://shikimori.io/api/animes/${t.apiId}`);const updated=animeFrom(a);Object.assign(t,updated,{poster:t.poster?.startsWith('assets/')?t.poster:updated.poster});}t.needsDetails=false;t.detailError=false;save();}catch{t.detailError=true;}finally{loadingDetails.delete(t.id);if(['title','watch'].includes(view)&&location.hash.endsWith('/'+t.id)){if(t.detailError)t.needsDetails=false;render();}}}


const playerStates=new Map();
function playerState(t){
 if(!playerStates.has(t.id)){
  const saved=state.players?.[t.id],session=state.activeWatch?.titleId===t.id?state.activeWatch:null;
  playerStates.set(t.id,{provider:saved?.provider||state.defaultPlayer||'kodik',episode:saved?.episode||session?.episode||nextEpisode(state,t.id),status:'idle',activated:!!session,baseUrl:'',error:'',request:0});
 }
 return playerStates.get(t.id);
}
function rememberPlayer(t){const p=playerState(t);state.players={...state.players,[t.id]:{provider:p.provider,episode:p.episode}};state.defaultPlayer=p.provider;}
function playerToolbar(t){
 const p=playerState(t),limit=available(t),max=Math.max(p.episode,limit??t.total??p.episode),total=Math.min(max,10000),coords=episodeCoordinates(t,p.episode);
 return `<label>Плеер<select id="inline-provider" class="select" data-id="${esc(t.id)}" aria-label="Плеер"><option value="kodik" ${p.provider==='kodik'?'selected':''}>Kodik</option><option value="turbo" ${p.provider==='turbo'?'selected':''}>Turbo</option></select></label><label>Серия<select id="inline-episode" class="select" data-id="${esc(t.id)}" aria-label="Серия в плеере">${Array.from({length:total},(_,i)=>`<option value="${i+1}" ${p.episode===i+1?'selected':''} ${limit!==null&&i+1>limit?'disabled':''}>${t.episodeData?.[i]?.label?esc(t.episodeData[i].label)+' · ':''}Серия ${i+1}${episodeWatched(state,t.id,i+1)?' ✓':''}</option>`).join('')}</select></label><span class="player-season">Сезон ${coords.season}</span><button class="text-link" data-action="reload-player" data-id="${esc(t.id)}">${icon('history')}Перезагрузить</button>`;
}
function playerProgress(t){
 const p=playerState(t),n=watched(t.id),seen=episodeWatched(state,t.id,p.episode),duration=t.episodeData?.[p.episode-1]?.duration||t.duration,limit=available(t);
 return `<div class="section-title">${icon('check')}<h2>Отметить просмотр</h2></div><div class="current-episode">${p.episode}<small>${esc(t.episodeData?.[p.episode-1]?.label||'Эпизод')}</small></div><p class="watch-session-status">${seen?'Эта серия уже отмечена':p.activated?'Смотрите и отмечайте на этой странице':'Запустите плеер, чтобы начать просмотр'}</p><div class="watch-facts"><span>Длительность<b>${duration?duration+' мин':'Не указана'}</b></span><span>Просмотрено<b>${n} / ${t.total||limit||'?'}</b></span><span>Время просмотра<b>${fmtTime(state.events.filter(e=>e.titleId===t.id).reduce((sum,e)=>sum+e.minutes,0))}</b></span></div><button class="btn complete-episode" data-action="complete-session" data-id="${esc(t.id)}" data-episode="${p.episode}" ${!p.activated||seen||!duration||t.needsDetails?'disabled':''}>${icon('check')}${seen?'Серия уже отмечена':'Просмотрено → следующая'}</button><button class="btn secondary" data-action="next-player-episode" data-id="${esc(t.id)}" ${limit!==null&&p.episode>=limit?'disabled':''}>Следующая серия ${icon('arrow')}</button><button class="btn ghost" data-action="undo" data-id="${esc(t.id)}" ${!n?'disabled':''}>${icon('back')}Отменить последнюю отметку</button><p class="tracking-note">Отмечается только выбранная серия. Повторный просмотр не добавляет время второй раз.</p><a class="text-link" href="#/history">История просмотров ${icon('arrow')}</a>`;
}
function inlinePlayerMarkup(t){
 const p=playerState(t);
 return `<section class="inline-player-section" id="inline-player" data-id="${esc(t.id)}"><div class="section-head"><div class="section-title">${icon('play')}<h2>Смотреть онлайн</h2></div><span class="filter-label">Kodik / Turbo</span></div><div class="embedded-layout"><div class="embedded-main"><div class="inline-toolbar">${playerToolbar(t)}</div><div class="inline-viewport"><div class="inline-placeholder">${icon('play')}<h3>Плеер на странице тайтла</h3><p>Выберите источник и серию — просмотр откроется здесь.</p><button class="btn" data-action="start-player" data-id="${esc(t.id)}">${icon('play')}Смотреть онлайн</button></div></div><div class="inline-player-status" role="status">${p.error?esc(p.error):'Видео предоставляется выбранным плеером. Отметка серии — справа или на нижней панели.'}</div></div><aside class="watch-progress inline-progress">${playerProgress(t)}</aside></div></section>`;
}
function detail(id){
 const t=getTitle(id);if(!t)return empty('Тайтл не найден','Выберите тайтл в каталоге.');
 const html=legacyDetail(id),cut=html.indexOf('<section class="tracking-panel">');
 return html.slice(0,cut)+inlinePlayerMarkup(t);
}
function watchPage(id){return detail(id);}
function refreshInlinePlayer(t){
 const toolbar=$('.inline-toolbar'),progress=$('.inline-progress');
 if(toolbar)toolbar.innerHTML=playerToolbar(t);if(progress)progress.innerHTML=playerProgress(t);
 const template=document.createElement('template');template.innerHTML=legacyDetail(t.id);
 if($('.detail-hero'))$('.detail-hero').replaceWith(template.content.querySelector('.detail-hero'));
 document.querySelectorAll('.status-link').forEach(link=>{const key=link.getAttribute('href').split('/').at(-1);link.querySelector('span:last-child').textContent=entries(key).length;});
 const badge=$('.nav-number');if(badge)badge.textContent=entries().length;
 document.querySelectorAll('.avatar').forEach(el=>el.textContent=state.name[0]?.toUpperCase()||'Я');
 const profileName=$('.profile-btn strong');if(profileName)profileName.textContent=state.name;
 const oldDock=$('.watch-dock');if(oldDock)oldDock.remove();$('.workspace').insertAdjacentHTML('beforeend',watchDock());
 mountInlinePlayer(t);
}
function mountInlinePlayer(t){
 const p=playerState(t),viewport=$('.inline-viewport');if(!viewport)return;
 const status=$('.inline-player-status');
 if(p.status==='ready'){
  const src=withEpisode(p.baseUrl,t,p.episode);let frame=$('#inline-iframe');
  if(!frame){viewport.innerHTML='';frame=document.createElement('iframe');frame.id='inline-iframe';frame.dataset.instance=crypto.randomUUID();frame.title=`${p.provider==='kodik'?'Kodik':'Turbo'} — ${t.title}`;frame.setAttribute('allow','autoplay; encrypted-media; fullscreen; picture-in-picture');frame.setAttribute('allowfullscreen','');frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-presentation allow-forms');frame.referrerPolicy='strict-origin-when-cross-origin';viewport.appendChild(frame);}
  if(frame.getAttribute('src')!==src)frame.setAttribute('src',src);
  status.textContent='Выберите озвучку и качество внутри плеера. После серии нажмите «Просмотрено → следующая».';
 }else if(p.status==='loading'){
  viewport.innerHTML='<div class="inline-placeholder"><span class="loading">Подключаем плеер…</span></div>';
  status.textContent='Загружаем выбранный источник.';
 }else if(p.status==='error'){
  viewport.innerHTML=`<div class="inline-placeholder">${icon('film')}<h3>Плеер пока недоступен</h3><p>${esc(p.error)}</p><button class="btn" data-action="reload-player" data-id="${esc(t.id)}">Попробовать ещё раз</button></div>`;
  status.textContent='Можно выбрать другой плеер в меню выше.';
 }else if(p.activated){startEmbeddedPlayer(t);}
}
async function playerMetadata(t,provider){
 if(t.kind==='tv'&&!t.imdbId&&t.apiId){const data=await fetchJson(`https://api.tvmaze.com/shows/${t.apiId}`);t.imdbId=data.externals?.imdb;}
 if(!kinopoiskId(t)&&t.kind==='anime'&&t.apiId){try{const data=await fetchJson(`https://shikimori.io/api/animes/${t.apiId}/external_links`);t.officialSources=data.filter(link=>link.kind==='kinopoisk').map(link=>({url:link.url}));}catch(err){if(provider==='turbo')throw err;}}
}
async function startEmbeddedPlayer(t,{reload=false}={}){
 const p=playerState(t);if(!reload&&p.status==='loading')return;
 if(!reload&&p.status==='ready'){document.getElementById('inline-player')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 const begin=beginWatching(state,t,'',Date.now(),p.episode);if(!begin.ok){toast(begin.reason);return;}
 p.activated=true;p.status='loading';p.error='';const request=++p.request,provider=p.provider;rememberPlayer(t);save();render();
 try{
  await playerMetadata(t,provider);
  const base=await providerFrameUrl(t,provider,fetchJson);
  if(request!==p.request)return;p.baseUrl=base;p.status='ready';save();
 }catch(err){if(request!==p.request)return;p.status='error';p.error=err.name==='TypeError'?'Не удалось подключиться к источнику. Выберите другой плеер.':err.message==='Каталог временно недоступен'?'Источник временно не отвечает. Попробуйте другой плеер.':err.name==='TimeoutError'?'Источник не ответил вовремя. Попробуйте другой плеер.':err.message||'Источник временно недоступен';}
 if(view==='title'&&location.hash.split('/')[2]===t.id){render();document.getElementById('inline-player')?.scrollIntoView({behavior:'smooth',block:'start'});}
}
function selectPlayerEpisode(t,episode){
 const p=playerState(t),limit=available(t);if(!Number.isInteger(episode)||episode<1||(limit!==null&&episode>limit))return;
 p.episode=episode;if(p.activated)beginWatching(state,t,p.baseUrl,Date.now(),episode);rememberPlayer(t);save();render();
}
function watchDock(){
 const session=state.activeWatch,t=getTitle(session?.titleId);if(!t)return '';
 const seen=episodeWatched(state,t.id,session.episode);
 return `<aside class="watch-dock" aria-label="Текущий просмотр"><a class="watch-dock-title" href="#/title/${esc(t.id)}"><img src="${safeUrl(t.poster)||'favicon.svg'}" alt=""><span><strong>${esc(t.title)}</strong><small>Серия ${session.episode} · вернуться к плееру</small></span></a><button class="btn" data-action="complete-session" data-id="${esc(t.id)}" data-episode="${session.episode}" ${seen||!t.duration||t.needsDetails?'disabled':''}>${icon('check')}${seen?'Уже отмечена':'Серия просмотрена'}</button><button class="icon-btn" data-action="close-session" aria-label="Закрыть панель просмотра">${icon('close')}</button></aside>`;
}
document.addEventListener('input',e=>{if(e.target.id==='search-input')searchDraft=e.target.value;});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.genre-filter'))genresOpen=e.target.open;},true);
document.addEventListener('change',e=>{
 const field=e.target;
 if(field.matches('[data-genre]')){searchFilters.genres=field.checked?[...searchFilters.genres,field.dataset.genre]:searchFilters.genres.filter(g=>g!==field.dataset.genre);search($('#search-input')?.value??query);}
 else if(['score-min','score-max'].includes(field.id)){const minimum=Number($('#score-min').value),maximum=Number($('#score-max').value);if(minimum>maximum){toast('Минимальная оценка не может быть выше максимальной');render();return;}searchFilters.minScore=minimum;searchFilters.maxScore=maximum;search($('#search-input')?.value??query);}
 else if(field.id==='search-order'){searchFilters.order=field.value;render();}
 else if(field.id==='inline-provider'){const t=getTitle(field.dataset.id),p=playerState(t);p.provider=field.value;p.status='idle';p.baseUrl='';p.error='';p.request++;rememberPlayer(t);save();if(p.activated)startEmbeddedPlayer(t,{reload:true});else render();}
 else if(field.id==='inline-episode')selectPlayerEpisode(getTitle(field.dataset.id),Number(field.value));
});
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');if(!button)return;
 const {action,id,value}=button.dataset;
 if(action==='reset-search'){searchFilters={genres:[],minScore:0,maxScore:10,order:'relevance'};kind='all';genresOpen=false;search($('#search-input')?.value??query);}
 else if(action==='remove-genre'){searchFilters.genres=searchFilters.genres.filter(g=>g!==value);search($('#search-input')?.value??query);}
 else if(action==='search-more')search(query,{append:true});

 else if(action==='start-player'||action==='reload-player'){const t=getTitle(id);if(t)startEmbeddedPlayer(t,{reload:action==='reload-player'});}
 else if(action==='next-player-episode'){const t=getTitle(id);if(t)selectPlayerEpisode(t,playerState(t).episode+1);}
 else if(action==='complete-session'){
  if(Date.now()-lastCompleteAt<900)return;
  const t=getTitle(id);if(!t)return;const selected=Number(button.dataset.episode),current=playerState(t);if(!state.activeWatch&&current.episode===selected)beginWatching(state,t,current.baseUrl,Date.now(),selected);const result=completeWatching(state,t,selected);
  if(!result.ok){render();toast(result.reason);return;}
  const p=playerState(t);if(state.activeWatch?.titleId===id)p.episode=state.activeWatch.episode;rememberPlayer(t);
  lastCompleteAt=Date.now();save();render();toast(`Серия ${result.event.episode} отмечена · +${result.event.minutes} мин`);
 }
 else if(action==='close-session'){state.activeWatch=null;save();render();}
});

function dialog(content){$('#profile-dialog').innerHTML=content;$('#profile-dialog').showModal();}
function dialogHead(title){return `<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>`;}
function profile(){dialog(`${dialogHead('Ваше пространство')}<form id="profile-form"><label class="field">Как вас называть?<input name="name" value="${esc(state.name)}" maxlength="35" required></label><button class="btn" type="submit">Сохранить</button></form><div class="separator"></div><p class="dialog-help">Данные сохраняются в этом браузере. Для переноса на другое устройство скачайте резервную копию и импортируйте её там.</p><div class="profile-actions"><button class="btn secondary" data-action="export">${icon('download')}Экспорт</button><label class="btn secondary" style="cursor:pointer">Импорт<input type="file" id="import-file" accept="application/json,.json" hidden></label></div>${state.demo?'<div class="separator"></div><button class="btn" data-action="start">Начать свою коллекцию</button>':''}`);}
function start(){if($('#profile-dialog').open)$('#profile-dialog').close();dialog(`${dialogHead('Начнём вашу историю')}<p class="dialog-help">Демо-коллекция уступит место вашему личному списку. Найдите первый тайтл и добавьте его в планы или начните смотреть.</p><form id="start-form"><label class="field">Как вас называть?<input name="name" placeholder="Ваше имя" maxlength="35" required autofocus></label><button class="btn" type="submit">Создать мой список ${icon('arrow')}</button></form>`);}
function manual(t=null){dialog(`${dialogHead(t?'Редактировать тайтл':'Добавить свой тайтл')}<form id="manual-form" ${t?`data-id="${esc(t.id)}"`:''}><label class="field">Название<input name="title" required maxlength="150" value="${esc(t?.title||query)}"></label><label class="field">Тип<select name="kind"><option value="anime" ${t?.kind==='anime'?'selected':''}>Аниме</option><option value="tv" ${t?.kind==='tv'?'selected':''}>Сериал</option></select></label><label class="field">Всего эпизодов (если известно)<input name="total" type="number" min="1" max="100000" value="${t?.total||''}" placeholder="Не объявлено"></label><label class="field">Сколько уже вышло<input name="released" type="number" min="0" max="100000" value="${t?.released??''}" required></label><label class="field">Длительность одного эпизода, минут<input name="duration" type="number" min="1" max="1440" required value="${t?.duration||24}"></label><button class="btn" type="submit">${t?'Сохранить':'Добавить в планы'}</button></form>`);}
function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state,catalog},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`yoru-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия скачана');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;if(action==='watch'){const t=getTitle(id);if(!t)return;const result=watch(state,t);if(result.ok){syncWatchSession(state,t);save();render();toast(`Эпизод ${result.event.episode} отмечен · +${result.event.minutes} мин`);}else toast(result.reason);}else if(action==='undo'){const removed=state.events.filter(e=>e.titleId===id).at(-1);undo(state,id);const t=getTitle(id);if(removed&&playerStates.has(id)){const p=playerState(t);p.episode=removed.episode;if(p.activated)beginWatching(state,t,p.baseUrl,Date.now(),p.episode);rememberPlayer(t);}else syncWatchSession(state,t);save();render();toast('Последняя отметка отменена, время пересчитано');}else if(action==='filter'){filter=value;location.hash='#/library'+(value==='all'?'':'/'+value);render();}else if(action==='kind'){kind=value;if(view==='search')search($('#search-input')?.value??query);else render();}else if(action==='profile')profile();else if(action==='start')start();else if(action==='close-dialog')$('#profile-dialog').close();else if(action==='export')exportData();else if(action==='manual')manual();else if(action==='edit-manual')manual(getTitle(id));else if(action==='refresh'){const t=getTitle(id);t.needsDetails=true;t.detailError=false;render();}else if(action==='menu'){menuOpen=!menuOpen;render();}else if(action==='duration'){dialog(`${dialogHead('Длительность эпизода')}<form id="duration-form" data-id="${esc(id)}"><label class="field">Минуты<input type="number" name="duration" min="1" max="1440" required></label><button class="btn" type="submit">Сохранить</button></form>`);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const data=new FormData(f);if(f.id==='global-search'||f.id==='catalog-search'){const q=String(data.get('q')||'');location.hash='#/search';search(q);}else if(f.id==='profile-form'){state.name=String(data.get('name')).trim()||'Зритель';save();$('#profile-dialog').close();render();toast('Профиль сохранён');}else if(f.id==='start-form'){state={name:String(data.get('name')).trim()||'Зритель',demo:false,entries:{},events:[],createdAt:new Date().toISOString()};filter='all';save();$('#profile-dialog').close();location.hash='#/dashboard';render();}else if(f.id==='manual-form'){const total=Number(data.get('total'))||null,released=Number(data.get('released'));if(total!==null&&released>total){toast('Вышедших серий не может быть больше общего числа');return;}const existing=getTitle(f.dataset.id);if(released<watched(existing?.id)){toast('Число вышедших серий меньше вашего прогресса');return;}const t={id:existing?.id||'custom-'+crypto.randomUUID(),kind:data.get('kind'),title:String(data.get('title')).trim(),original:'Добавлено вами',total,released,duration:Number(data.get('duration')),genres:[],description:'',airing:total===null||released<total};if(!t.title)return;if(existing)Object.assign(existing,t);else{catalog.push(t);state.entries[t.id]={status:'planned',updatedAt:Date.now()};}save();$('#profile-dialog').close();location.hash='#/title/'+t.id;render();}else if(f.id==='duration-form'){getTitle(f.dataset.id).duration=Number(data.get('duration'));save();$('#profile-dialog').close();render();}});
document.addEventListener('change',async e=>{if(e.target.id==='title-status'){const id=e.target.dataset.id,status=e.target.value;if(!status)return;state.entries[id]={...state.entries[id],status,updatedAt:Date.now()};save();render();toast('Статус изменён. Серии отмечаются отдельно.');}else if(e.target.id==='sort-select'){sort=e.target.value;render();}else if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>15e6)throw Error('Файл слишком большой');const data=validateBackup(JSON.parse(await file.text()));dialog(`${dialogHead('Восстановить коллекцию?')}<p class="dialog-help">Профиль «${esc(data.state.name)}»: ${Object.keys(data.state.entries).length} тайтлов, ${data.state.events.length} эпизодов. Импорт заменит текущую коллекцию. Сначала можно экспортировать её резервную копию.</p><div class="profile-actions"><button class="btn secondary" data-action="export">Экспорт текущей</button><button class="btn" id="confirm-import">Восстановить</button></div>`);$('#confirm-import').onclick=()=>{state={...data.state,demo:false};catalog=data.catalog;save();$('#profile-dialog').close();location.hash='#/dashboard';render();toast('Коллекция восстановлена');};}catch(err){toast(err.message||'Не удалось прочитать файл');}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search input').focus();}});
window.addEventListener('hashchange',()=>{menuOpen=false;render();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const data=JSON.parse(e.newValue);state=data.state;catalog=data.catalog;render();}catch{}}});
try{
 catalog=await fetchJson('./catalog.json');
 let stored;
 try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
 if(stored?.state&&Array.isArray(stored.catalog)){
  catalog=[...stored.catalog,...catalog.filter(t=>!stored.catalog.some(s=>s.id===t.id))];
  if(stored.state.demo){
   try{localStorage.setItem(`${KEY}-demo-backup`,JSON.stringify(stored));}catch{}
   state=emptyState();save();
  }else state=stored.state;
 }else{state=emptyState();save();}
 render();
}catch{$('#app').innerHTML='<div class="boot">yoru<span>Не удалось загрузить каталог. Обновите страницу.</span></div>';}
